create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$ begin
 if value is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.expect_error(statement text,pattern text,label text) returns void language plpgsql as $$ declare failed boolean:=false; begin
 begin execute statement; exception when others then
   if position(pattern in sqlerrm)=0 then raise exception 'Wrong error for %: %',label,sqlerrm; end if; failed:=true;
 end;
 if not failed then raise exception 'Expected rejection: %',label; end if; raise notice 'PASS: %',label;
end $$;
select pg_temp.assert_true((select verification='confirmed' from articles where id='11111111-1111-4111-8111-111111111111'),'legacy article not mass-demoted');
select pg_temp.assert_true((select translation_status='published' from article_translations where id='33333333-3333-4333-8333-333333333333'),'legacy translation not mass-demoted');
select pg_temp.assert_true((select count(*)=1 from article_change_log where before_snapshot is not null),'prior private snapshots preserved');
set role anon;
select pg_temp.expect_error('select id from public.articles limit 1','permission denied','anon cannot read article table');
select pg_temp.expect_error('select trust_review_note from public.articles limit 1','permission denied','anon inherited private column grant revoked');
select pg_temp.expect_error('select id from public.article_translations limit 1','permission denied','anon inherited translation table grant revoked');
select pg_temp.expect_error($q$select * from get_editor_article_trust(array['11111111-1111-4111-8111-111111111111'::uuid])$q$,'permission denied','anon cannot execute editor metadata RPC');
select pg_temp.expect_error('select id from public.article_evidence limit 1','permission denied','anon cannot read evidence table');
select pg_temp.expect_error('select id from public.article_change_log limit 1','permission denied','anon cannot read audit table');
select pg_temp.assert_true(get_public_article_trust('22222222-2222-4222-8222-222222222222') is null,'review article absent publicly');
select pg_temp.assert_true(get_public_article_trust('44444444-4444-4444-8444-444444444444') is null,'future published article absent from public trust');
select pg_temp.assert_true(get_public_article_trust('55555555-5555-4555-8555-555555555555') is null,'undated published article absent from public trust');
select pg_temp.assert_true(get_public_article_trust('66666666-6666-4666-8666-666666666666') is null,'rejected fixture absent publicly');
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->>'source_url'='https://example.org/original','story URL preferred over RSS feed');
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->>'editorial_trust_status'='unconfirmed','legacy counts do not imply human confirmation');
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->'history'='[]','old snapshots excluded from public history');
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->'reviewed_translation'='null'::jsonb,'legacy unreviewed translation excluded');
reset role;
select set_config('test.jwt','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","app_metadata":{"role":"reader"},"user_metadata":{"role":"admin"}}',false);
set role authenticated;
select pg_temp.expect_error($q$select review_article_trust('11111111-1111-4111-8111-111111111111','confirmed','pretend review')$q$,'Editor/admin required','user metadata cannot elevate');
select pg_temp.assert_true((select title='Fixture story' and summary='Fixture text' and source_url='https://example.org/feed.xml' from articles where id='11111111-1111-4111-8111-111111111111'),'regular authenticated newsroom safe reads retained');
select pg_temp.assert_true((select count(*)=0 from articles where editorial_status in ('review','rejected')),'regular authenticated article drafts stay hidden');
