select pg_temp.assert_true((select title='ترجمة قديمة' from article_translations where id='33333333-3333-4333-8333-333333333333'),'legacy published newsroom translation retained');
select pg_temp.assert_true((select count(*)=0 from article_translations where translation_status in ('draft','review','rejected')),'regular authenticated translation draft/rejected reads return no rows');
