select pg_temp.expect_error('select * from public.article_translations limit 1','permission denied','reader translation SELECT star denied');
select pg_temp.expect_error('select human_review_note from public.article_translations limit 1','permission denied','reader private translation review notes denied');
select pg_temp.expect_error('select reviewed_by from public.article_translations limit 1','permission denied','reader translation reviewer IDs denied');
select pg_temp.expect_error($q$select * from get_editor_article_trust(array['11111111-1111-4111-8111-111111111111'::uuid])$q$,'Editor/admin required','reader metadata RPC denies user_metadata elevation');
select pg_temp.assert_true((select count(*)=0 from public.article_evidence),'non-editor evidence read denied by RLS');
reset role;
select set_config('test.jwt','{}',false);
set role service_role;
select pg_temp.assert_true((select trust_review_note='INTERNAL_STORY_NOTE' and human_translation_note='INTERNAL_TRANSLATION_NOTE' from articles where id='11111111-1111-4111-8111-111111111111'),'server-only service metadata reads retained');
select pg_temp.assert_true((select count(*)=6 from article_translations),'service retains draft queue reads');
select pg_temp.assert_true((select count(*)=1 from articles where id='22222222-2222-4222-8222-222222222222'),'service retains nonpublished article reads');
reset role;
select set_config('test.jwt','{"app_metadata":{"role":"editor"}}',false);
set role authenticated;
select pg_temp.expect_error($q$select * from get_editor_article_trust(array['11111111-1111-4111-8111-111111111111'::uuid])$q$,'Editor/admin required','editor role without human identity cannot read metadata');
