select set_config('test.jwt','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","app_metadata":{"role":"editor"}}',false);
-- Base already unconfirmed/pending: ONLY each language field changes, so the
-- audit early return must not preserve a dependent translation's certification.
update articles set human_translation_status='pending' where id='11111111-1111-4111-8111-111111111111';
select review_article_translation('33333333-3333-4333-8333-333333333333','published','Language regression review');
update articles set source_language='fr' where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true((select translation_status='review' and reviewed_by is null from article_translations where id='33333333-3333-4333-8333-333333333333'),'source-language-only edit invalidates dependent translation');
select pg_temp.assert_true((select count(*)>0 from article_change_log where article_id='11111111-1111-4111-8111-111111111111' and changed_fields ? 'source_language'),'source-language edit is audited before early return');
select review_article_translation('33333333-3333-4333-8333-333333333333','published','Language regression rereview');
update articles set lang='de' where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true((select translation_status='review' and reviewed_by is null from article_translations where id='33333333-3333-4333-8333-333333333333'),'lang-only edit invalidates dependent translation');
select pg_temp.assert_true((select count(*)>0 from article_change_log where article_id='11111111-1111-4111-8111-111111111111' and changed_fields ? 'lang'),'lang-only edit is audited before early return');
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->'reviewed_translation'='null'::jsonb,'invalidated translation cannot remain publicly certified');
select review_article_translation('33333333-3333-4333-8333-333333333333','published','Rereview before source content edit');
update articles set summary='Changed source text after translation review' where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true((select translation_status='review' and reviewed_by is null from article_translations where id='33333333-3333-4333-8333-333333333333'),'changed original invalidates dependent translation review');
select pg_temp.assert_true((select human_translation_status='pending' and editorial_trust_status='unconfirmed' from articles where id='11111111-1111-4111-8111-111111111111'),'changed text resets article-level translation and trust');
select pg_temp.expect_error($q$select review_article_translation('ffffffff-ffff-4fff-8fff-ffffffffffff','published','missing row')$q$,'Translation not found','translation RPC reports missing row');
-- History remains private and intact even if the article itself is deleted.
delete from articles where id='22222222-2222-4222-8222-222222222222';
select pg_temp.assert_true((select count(*)>0 from article_change_log where article_id='22222222-2222-4222-8222-222222222222'),'history retained after article deletion');
select pg_temp.expect_error($q$update article_translations set translation_source='editorial' where id='33333333-3333-4333-8333-333333333333'$q$,'provenance cannot be relabeled','machine origin cannot be falsified through direct update');
select review_article_trust('11111111-1111-4111-8111-111111111111','unconfirmed','Current uncertainty recorded');
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->'claims'->0->>'status'='unconfirmed','public claim remains uncertain after changed evidence even when story reviewed as unconfirmed');
select pg_temp.expect_error($q$select review_article_trust('11111111-1111-4111-8111-111111111111','confirmed','stale support','reviewed','Compared source')$q$,'changed since its human review','human story review cannot reuse stale claim evidence');
update articles set url=null where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->>'source_url'='https://example.org/feed.xml','missing story URL falls back to safe source URL');
update articles set url='javascript:alert(1)' where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->>'source_url'='https://example.org/feed.xml','unsafe story URL falls back to safe source URL');
update articles set source_url='javascript:alert(1)' where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111')->>'source_url' is null,'neither unsafe URL is publicly returned');
update articles set editorial_status='rejected' where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true(get_public_article_trust('11111111-1111-4111-8111-111111111111') is null,'rejected article excluded from public RPC');
delete from articles where id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert_true((select count(*)>0 from article_change_log where article_id='11111111-1111-4111-8111-111111111111'),'cascade article deletion preserves all audit history');
